{
  "schemaVersion": "0.2",
  "slug": "steps",
  "name": "Steps",
  "family": "B",
  "status": "experimental",
  "purpose": "Shows sequential progress through a named series of steps, optionally allowing jump selection.",
  "scenarios": [
    "Walk through a multi-step checkout",
    "Show onboarding progress",
    "Jump back to a completed setup step"
  ],
  "props": {
    "items": {
      "type": "node",
      "required": true,
      "description": "Ordered steps with value, label, and optional description."
    },
    "currentValue": {
      "type": "string",
      "required": true,
      "description": "Value of the current step."
    },
    "onSelect": {
      "type": "event",
      "required": false,
      "description": "When provided, each step is a button that reports its value."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the steps landmark."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "start",
      "description": "The first step is current."
    },
    {
      "name": "in-progress",
      "description": "A middle step is current."
    },
    {
      "name": "complete",
      "description": "The last step is current."
    }
  ],
  "composition": {
    "allowedParents": ["container", "card", "dialog", "page"],
    "allowedChildren": ["text", "button"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use Steps for peer section switching; use Tabs or Navbar.",
    "Do not skip announcing the current step; aria-current=step is required."
  ],
  "a11y": {
    "role": "navigation",
    "keyboard": [
      "Tab moves through step buttons when interactive",
      "Enter or Space activates a step button"
    ],
    "focus": "Interactive steps are buttons in document order with a visible focus ring.",
    "labeling": "The landmark has an accessible name; the current step uses aria-current=step.",
    "wcag": ["1.3.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Root is a query container. Compact stacks steps; tablet/desktop place them in a row. No viewport size media.",
    "breakpoints": {
      "compact": "Vertical list; 44px targets.",
      "medium": "Horizontal list at 48rem container width.",
      "large": "Wider gap at 80rem container width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Row direction follows document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "steps",
    "states": ["start", "in-progress", "complete"],
    "intents": ["enumerate-items"]
  }
}

import './styles.css'

export interface StepItem {
  value: string
  label: string
  description?: string
}

export type StepsStatus = 'start' | 'in-progress' | 'complete'

function statusFor(currentIndex: number, lastIndex: number): StepsStatus {
  if (currentIndex <= 0) return 'start'
  if (currentIndex >= lastIndex) return 'complete'
  return 'in-progress'
}

export interface StepsProps {
  items: StepItem[]
  currentValue: string
  onSelect?: (value: string) => void
  label: string
  className?: string
}

export function Steps({ items, currentValue, onSelect, label, className }: StepsProps) {
  const classes = ['cu-steps', className].filter(Boolean).join(' ')
  const currentIndex = items.findIndex((item) => item.value === currentValue)
  const state = statusFor(currentIndex, Math.max(0, items.length - 1))

  return (
    <nav className={classes} aria-label={label} data-ai-role="steps" data-ai-intent="enumerate-items" data-ai-state={state}>
      <ol className="cu-steps__list">
        {items.map((item, index) => {
          const status = index < currentIndex ? 'complete' : index === currentIndex ? 'current' : 'upcoming'
          const content = (
            <>
              <span className="cu-steps__index" aria-hidden="true">
                {index + 1}
              </span>
              <span className="cu-steps__copy">
                <span className="cu-steps__label">{item.label}</span>
                {item.description ? <span className="cu-steps__description">{item.description}</span> : null}
              </span>
            </>
          )
          return (
            <li key={item.value} className={'cu-steps__item cu-steps__item--' + status} data-status={status}>
              {onSelect ? (
                <button
                  type="button"
                  className="cu-steps__button"
                  aria-current={status === 'current' ? 'step' : undefined}
                  onClick={() => onSelect(item.value)}
                >
                  {content}
                </button>
              ) : (
                <div className="cu-steps__static" aria-current={status === 'current' ? 'step' : undefined}>
                  {content}
                </div>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

/*
 * Query container: the nav is the container; the list consumes it so the
 * stack -> row morph follows the stepper's own inline size rather than the
 * viewport. 48rem == breakpoint.tablet, 80rem == breakpoint.desktop
 * (packages/tokens/src/core/breakpoint.json).
 */
.cu-steps {
  color: var(--cu-color-fg-default);
  container-type: inline-size;
}

.cu-steps__list {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-steps__item {
  display: flex;
  flex: 1;
  min-inline-size: 0;
}

.cu-steps__button,
.cu-steps__static {
  display: flex;
  align-items: center;
  gap: var(--cu-space-2);
  inline-size: 100%;
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
  text-align: start;
}

.cu-steps__button {
  cursor: pointer;
}

.cu-steps__button:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-steps__index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border-radius: 999px;
  border: 1px solid var(--cu-color-border-default);
  font-weight: 700;
}

.cu-steps__item--current .cu-steps__index {
  background: var(--cu-color-palette-brand);
  border-color: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
}

.cu-steps__item--complete .cu-steps__index {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 18%, var(--cu-color-background-default));
  border-color: var(--cu-color-palette-brand);
}

.cu-steps__copy {
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-steps__label {
  font-weight: 650;
}

.cu-steps__description {
  font-size: 0.875em;
}

@media (hover: hover) {
  .cu-steps__button:hover {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

@container (min-width: 48rem) {
  .cu-steps__list {
    flex-direction: row;
    align-items: stretch;
  }
}

@container (min-width: 80rem) {
  .cu-steps__list {
    gap: var(--cu-space-3);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-steps__button {
    transition-duration: 0.01ms;
  }
}
